import { Component, OnDestroy, OnInit } from '@angular/core';
import { GovBrTabModule } from '@serpro/ngx-dsgovbr';
import { CommonModule } from '@angular/common';
import { MyTitleComponent } from '../diversos/my-title/my-title.component';
import { ValidadorGrupoComponent } from './validador-grupo/validador-grupo.component';
import { ValidadorNotaComponent } from './validador-nota/validador-nota.component';
import { MensagemService } from '../../services/mensagem.service';
import { DispositivoService } from '../../services/dispositivo.service';
import { Subscription } from 'rxjs';
import { Router } from '@angular/router';
import { XmlService } from '../../services/xml.service';

@Component({
  selector: 'validador-xml',
  templateUrl: './validador-xml.component.html',
  styleUrl: './validador-xml.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    GovBrTabModule,
    MyTitleComponent,
    ValidadorGrupoComponent,
    ValidadorNotaComponent,
],
  providers: [],
})
export class ValidadorXmlComponent implements OnInit, OnDestroy {

  private subscriptions: Subscription = new Subscription();
  dispositivo: string = '';

  constructor(
    private mensagemService: MensagemService,
    private dispositivoService: DispositivoService,
    private router: Router,
    private xmlService: XmlService
  ) { }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    this.mensagemService.limpar();
  }

  ngOnInit(): void {
    if (this.xmlService.tiposDeDocumentoValidacao.length === 0) {
      this.xmlService.obterDocumentosNaValidacao().subscribe({
        next: (data) => {
          this.xmlService.tiposDeDocumentoValidacao = data;
        },
        error: (error) => {
          console.error('Erro ao carregar documentos de validação:', error);
        }
      });
    }
    this.setSubscriptions();
  }

  voltar() {
    this.router.navigate(['/calculadora']);
  }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo: any) => {
        this.dispositivo = dispositivo;
        if (this.dispositivo === 'device-xsmall') {

        } else {

        }
      }));
  }

}
